const base = "https://ghproxy.net/https://raw.githubusercontent.com/mattpocock/skills/main/";
const q = (s: string) => s;
const cmd = [
  `$r = curl.exe -sS -m 25 -L "${base}docs/productivity/grill-me.md"`,
  `$t = ($r -join [char]10)`,
  `"=== grill-me.md head (len " + $t.Length + ") ==="`,
  `$t.Substring(0, 1400)`,
  `$g = (curl.exe -sS -m 25 -L "${base}skills/productivity/grilling/SKILL.md") -join [char]10`,
  `""; "=== grilling/SKILL.md (len " + $g.Length + ") ==="`,
  `$g`,
].join("\n");
const out = await tools.pwsh({ command: cmd, description: "Fetch grilling engine skill source", timeoutMs: 90000 });
if (out.kind === "foreground") console.log(out.stdout.text.slice(0, 9000), "\nSTDERR:", out.stderr.text.slice(0, 300), "exit", out.exitCode);
